// The out-of-line body of ai.h's sort predicate. /Ob2 folds it into
// the _Insertion_sort instantiation - retail emits no standalone copy.
bool func_moves_before::operator()(const army* a, const army* b) const
{
    if (a->field_190 > b->field_190)
        return true;
    if (a->field_190 < b->field_190)
        return false;
    return a->bitIndex < b->bitIndex;
}

