        if (friendly->Is(3) & 1) {
            long damage = friendly->get_average_damage(our_army, 0,
                                                       friendly->numTroops,
                                                       1, 0);
            melee_value = our_army->get_loss_combat_value(
                    estimate->lowest_attack, estimate->lowest_defense,
                    our_army->can_shoot(0), damage, 0);
        } else {
            melee_value = 0;
        }
        if (area_effect == 0 && melee_value == 0)
            continue;
